#!/usr/bin/env python
"""Analyze system_info class structure without importing numpy"""

import ast
import os

def analyze_class(filepath, class_name):
    """Analyze a class in a Python file"""
    with open(filepath, 'r') as f:
        content = f.read()

    tree = ast.parse(content)

    class_info = {
        'name': class_name,
        'methods': [],
        'lines': 0,
        'start_line': 0,
        'end_line': 0
    }

    for node in ast.walk(tree):
        if isinstance(node, ast.ClassDef) and node.name == class_name:
            class_info['start_line'] = node.lineno
            class_info['end_line'] = max(getattr(n, 'end_lineno', node.lineno) for n in ast.walk(node))
            class_info['lines'] = class_info['end_line'] - class_info['start_line'] + 1

            # Count methods
            for item in node.body:
                if isinstance(item, ast.FunctionDef):
                    class_info['methods'].append(item.name)

            # Find subclass relationships
            for base in node.bases:
                if isinstance(base, ast.Name):
                    class_info['parent'] = base.id
                elif isinstance(base, ast.Attribute):
                    class_info['parent'] = ast.unparse(base)

            break

    return class_info

def count_subclasses(filepath, base_class):
    """Count subclasses of a base class"""
    with open(filepath, 'r') as f:
        content = f.read()

    tree = ast.parse(content)
    subclasses = []

    for node in ast.walk(tree):
        if isinstance(node, ast.ClassDef):
            for base in node.bases:
                if isinstance(base, ast.Name) and base.id == base_class:
                    subclasses.append(node.name)
                elif isinstance(base, ast.Attribute):
                    # Handle cases like numpy.distutils.system_info.system_info
                    if base.attr == base_class:
                        subclasses.append(node.name)

    return subclasses

def analyze_method_overrides(filepath, base_class, subclasses):
    """Analyze which methods are overridden by subclasses"""
    with open(filepath, 'r') as f:
        content = f.read()

    tree = ast.parse(content)

    # Get base class methods
    base_methods = set()
    for node in ast.walk(tree):
        if isinstance(node, ast.ClassDef) and node.name == base_class:
            for item in node.body:
                if isinstance(item, ast.FunctionDef):
                    base_methods.add(item.name)
            break

    # Track overrides
    overrides = {}
    for subclass in subclasses:
        for node in ast.walk(tree):
            if isinstance(node, ast.ClassDef) and node.name == subclass:
                subclass_methods = set()
                for item in node.body:
                    if isinstance(item, ast.FunctionDef):
                        subclass_methods.add(item.name)

                # Find overrides
                overrides[subclass] = subclass_methods.intersection(base_methods)
                break

    return base_methods, overrides

if __name__ == '__main__':
    filepath = '/workspace/project/numpy/numpy/distutils/system_info.py'
    base_class = 'system_info'

    print(f"Analyzing {filepath}")
    print("=" * 80)

    # Analyze base class
    base_info = analyze_class(filepath, base_class)
    print(f"Base class: {base_info['name']}")
    print(f"Lines of code: {base_info['lines']}")
    print(f"Number of methods: {len(base_info['methods'])}")
    print(f"Methods: {sorted(base_info['methods'])}")
    print()

    # Count subclasses
    subclasses = count_subclasses(filepath, base_class)
    print(f"Number of subclasses: {len(subclasses)}")
    print(f"Subclasses: {sorted(subclasses)}")
    print()

    # Analyze method overrides
    base_methods, overrides = analyze_method_overrides(filepath, base_class, subclasses)

    print("Method override analysis:")
    print("-" * 80)

    override_counts = {}
    for method in base_methods:
        override_counts[method] = 0

    for subclass, methods in overrides.items():
        for method in methods:
            override_counts[method] = override_counts.get(method, 0) + 1

    # Sort by most overridden
    sorted_counts = sorted(override_counts.items(), key=lambda x: x[1], reverse=True)

    print(f"{'Method':<30} {'Times Overridden':<20} {'Percentage':<10}")
    print("-" * 80)
    for method, count in sorted_counts:
        if count > 0:
            percentage = (count / len(subclasses)) * 100
            print(f"{method:<30} {count:<20} {percentage:.1f}%")

    print()

    # Show methods never overridden
    never_overridden = [method for method, count in sorted_counts if count == 0]
    print(f"Methods never overridden ({len(never_overridden)}):")
    for method in sorted(never_overridden):
        print(f"  - {method}")

